  algoNeedQuality: { ru: 'нужно качество {value}', en: 'needs quality {value}' },
  algoPending: { ru: 'Будет внедрён при переходе к следующему месяцу: разовые {cost}.', en: 'Will be rolled out when you run the next month: a one-off {cost}.' },

