  premiereNote: { ru: 'Премьера: {list}. Шум привёл подписчиков — но через месяц те, кто пришёл только ради неё, начнут уходить.', en: 'Premiere: {list}. The buzz brought subscribers in — but a month from now the ones who came only for it will start leaving.' },
  premiereItem: { ru: '{genre} (качество {quality})', en: '{genre} (quality {quality})' },
